-- Migration: Year 2 - Sexual & Forensic Pathology MCQs Part 6 (196-235)
-- Date: 2026-04-24

BEGIN;

DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    INSERT INTO topics (title, slug, semester_id, year_id, "order")
    VALUES ('Sexual & Forensic Pathology', 'sexual-forensic-pathology', 3, 2, 62)
    ON CONFLICT (slug) DO UPDATE SET year_id = 2, semester_id = 3
    RETURNING id INTO v_topic_id;

    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES

    -- BREAST: INFLAMMATORY & BENIGN (196-210)
    (v_topic_id, 'Acute Mastitis usually occurs during the first weeks of breastfeeding. What is the most common causative organism?', '["Streptococcus pyogenes", "Staphylococcus aureus", "Escherichia coli", "Candida albicans"]', 1, 'Acute mastitis is typically due to S. aureus entering through cracks in the nipple during lactation. It presents with a warm, erythematous, painful breast and fever. Treatment involves continued drainage (feeding) and antibiotics (e.g., dicloxacillin).'),
    (v_topic_id, 'Periductal Mastitis is strongly associated with which risk factor?', '["Obesity", "Cigarette smoking (causing vitamin A deficiency and squamous metaplasia of lactiferous ducts)", "Breastfeeding", "Advanced age"]', 1, 'Periductal mastitis involves inflammation of the subareolar ducts. Smoking leads to squamous metaplasia of the duct lining, causing keratin plugs that obstruct the duct and lead to inflammation and abscess formation.'),
    (v_topic_id, 'Mammary Duct Ectasia presents with a periareolar mass and "green-brown" nipple discharge. In whom does it typically occur?', '["Lactating women", "Postmenopausal women", "Teenagers", "Men"]', 1, 'Duct ectasia is a non-neoplastic inflammation and dilation of subareolar ducts. The characteristic discharge is due to the accumulation of debris and inflammation. It can mimic a breast mass.'),
    (v_topic_id, 'Fat Necrosis of the breast often presents as a painless, firm mass or as calcifications on mammography. What is the typical history?', '["Breastfeeding", "Trauma to the breast", "Family history of cancer", "Smoking"]', 1, 'Fat necrosis is usually due to trauma. Histologically, it shows necrotic fat, foamy macrophages (foamy cytoplasm), and calcifications (saponification). It can mimic breast cancer clinically and radiologically.'),
    (v_topic_id, 'Fibrocystic Changes (FCC) are the most common cause of breast "lumps." Which histological feature of FCC carries an increased risk for invasive carcinoma?', '["Simple cysts", "Sclerosing adenosis", "Atypical hyperplasia (ductal or lobular)", "Apocrine metaplasia"]', 2, 'Most FCC (fibrosis, cysts, apocrine metaplasia) have no increased risk. Sclerosing adenosis and ductal hyperplasia (without atypia) have a 1.5-2x risk. Atypical hyperplasia has a 4-5x increased risk for future breast cancer in either breast.'),
    (v_topic_id, 'Intraductal Papilloma classically presents with?', '["A painless firm mass", "Bloody nipple discharge in a premenopausal woman", "Nipple retraction", "Peau d''orange"]', 1, 'Intraductal papilloma is a benign growth in a large duct. It is the most common cause of bloody nipple discharge. It must be distinguished from papillary carcinoma (papillary carcinoma is seen in older women and lacks a myoepithelial cell layer).'),
    (v_topic_id, 'What is the most common benign tumor of the breast?', '["Phyllodes tumor", "Fibroadenoma (a mobile, marble-like mass in a young woman)", "Lipoma", "Hamartoma"]', 1, 'Fibroadenomas are benign proliferations of both fibrous stroma and glandular tissue. They are well-circumscribed and estrogen-sensitive (enlarge during pregnancy, shrink after menopause). They carry no increased risk of cancer.'),
    (v_topic_id, 'How does a Phyllodes Tumor differ from a Fibroadenoma?', '["Phyllodes is always small", "Phyllodes has an overgrowth of the stromal component and can be malignant (leaf-like projections on histology); it typically occurs in older women", "Phyllodes is purely glandular", "Phyllodes occurs only in males"]', 1, 'Phyllodes tumors have much more cellular stroma than fibroadenomas. While most are benign, some can be malignant and metastasize hematogenously. Grossly, they show a "leaf-like" (phyllodes) appearance.'),

    -- BREAST CANCER: MALIGNANT (211-235)
    (v_topic_id, 'Ductal Carcinoma In Situ (DCIS) is usually detected by?', '["Palpable mass", "Calcifications on mammography (as DCIS does not usually form a mass)", "Nipple discharge", "Ultrasound only"]', 1, 'DCIS cells proliferate within the duct but do not invade. Necrosis in the center of the duct can calcify, making it detectable on mammograms. "Comedocarcinoma" is a high-grade DCIS with central necrosis and dystrophic calcification.'),
    (v_topic_id, 'Paget Disease of the Nipple presents as a scaly, eczematous lesion of the nipple. What does it signify?', '["Fungal infection", "Underlying DCIS or invasive ductal carcinoma that has extended up the lactiferous ducts to reach the nipple skin", "Fat necrosis", "Simple dermatitis"]', 1, 'Paget cells are large, malignant cells with clear cytoplasm (Paget cells) found within the epidermis of the nipple. Unlike extramammary Paget, nipple Paget almost always implies an underlying breast malignancy.'),
    (v_topic_id, 'Invasive Ductal Carcinoma (IDC) is the most common type of invasive breast cancer. What is its characteristic gross appearance?', '["Soft, cystic mass", "Firm, ''gritty,'' stellate (star-shaped) mass with dimpling of the skin or nipple retraction", "Multiple small nodules", "Diffuse thickening"]', 1, 'IDC often induces a "desmoplastic" (fibrotic) response, which makes the tumor feel hard and pull on surrounding tissues (causing dimpling). It accounts for ~80% of all breast cancers.'),
    (v_topic_id, 'Invasive Lobular Carcinoma (ILC) is unique because of which histological feature?', '["Gland formation", "Cells growing in an ''orderly, single-file'' pattern (due to loss of E-cadherin adhesion protein)", "Psammoma bodies", "Starry-sky pattern"]', 1, 'ILC often lacks a desmoplastic response and may not form a distinct mass. The loss of E-cadherin (CDH1 mutation) means the cells do not stick together, resulting in the "single-file" (Indian file) growth pattern. It is often bilateral and multicentric.'),
    (v_topic_id, 'Medullary Carcinoma of the breast is characterized by sheets of high-grade cells and a prominent lymphocytic infiltrate. It is more common in which population?', '["Elderly women", "BRCA1 mutation carriers", "Men", "Postmenopausal women"]', 1, 'Medullary carcinoma is a rare subtype with a relatively better prognosis than standard IDC, despite its high-grade appearance. It is classically associated with BRCA1 mutations.'),
    (v_topic_id, 'Inflammatory Breast Carcinoma is a clinical diagnosis. What is the pathological hallmark?', '["Massive inflammatory infiltrate", "Tumor cells within dermal lymphatic vessels, causing ''peau d''''orange'' (orange peel skin)", "Acute mastitis", "Rupture of a cyst"]', 1, 'Inflammatory carcinoma is highly aggressive. The "peau d''orange" appearance is not due to inflammation but to lymphedema caused by cancer cells plugging the lymphatic drainage of the skin. It has a poor prognosis.'),
    (v_topic_id, 'What is the most important prognostic factor for breast cancer (once metastasis is excluded)?', '["Tumor size", "Axillary lymph node involvement", "Histological grade", "Patient age"]', 1, 'While size and grade are important, the presence and number of involved axillary lymph nodes is the single most important prognostic indicator for overall survival in localized disease.'),
    (v_topic_id, 'Which molecular marker, when overexpressed, predicts response to Trastuzumab (Herceptin)?', '["Estrogen Receptor (ER)", "HER2/neu (ERBB2) amplification", "Progesterone Receptor (PR)", "p53 mutation"]', 1, 'HER2 is a growth factor receptor. Herceptin is a monoclonal antibody that targets this receptor. Triple-negative breast cancer (ER-, PR-, HER2-) is more aggressive and has fewer targeted treatment options.'),
    (v_topic_id, 'A 45-year-old woman with a history of breast cancer in her mother and sister develops a new breast mass. A biopsy shows medullary carcinoma. Which gene mutation is most likely?', '["BRCA2", "BRCA1", "TP53", "RB1"]', 1, 'BRCA1 mutations are associated with medullary carcinoma and triple-negative breast cancer, as well as ovarian serous carcinoma. BRCA2 is more associated with male breast cancer.'),
    (v_topic_id, 'Male breast cancer is rare. What is the most common risk factor?', '["Obesity", "BRCA2 mutation or Klinefelter Syndrome", "History of mastitis", "Smoking"]', 1, 'Male breast cancer presents as a subareolar mass (since there are no lobules, it is almost always invasive ductal carcinoma). Klinefelter (47,XXY) and BRCA2 are the primary genetic associations.'),
    (v_topic_id, 'Fat necrosis and Mammary duct ectasia can both mimic breast cancer. How are they best distinguished from malignancy?', '["By biopsy (essential to confirm the benign nature of the lesion)", "By checking for fever", "By ultrasound only", "By serum markers"]', 0, 'Because these benign conditions can present with a firm mass and skin dimpling (fat necrosis) or nipple retraction (duct ectasia), biopsy is required to definitively rule out cancer.')

    ON CONFLICT DO NOTHING;

END $$;

COMMIT;
